-- ----------------------------
-- Table structure for request_logs
-- ----------------------------
DROP TABLE IF EXISTS `request_logs`;
CREATE TABLE `request_logs`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '日志ID',
  `seq` bigint NOT NULL AUTO_INCREMENT COMMENT '自增序列号',
  `api_key_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'API密钥ID',
  `api_key_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'API密钥名称',
  `channel_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '渠道ID',
  `channel_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '渠道名称',
  `model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求模型',
  `upstream_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上游实际模型',
  `mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '调用模式(chat/completion/embedding)',
  `protocol_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '协议类型(http/sse/websocket)',
  `stream` tinyint NULL DEFAULT 0 COMMENT '是否流式: 0=否 1=是',
  `is_retry` tinyint NULL DEFAULT 0 COMMENT '是否重试: 0=否 1=是',
  `status_code` int NULL DEFAULT NULL COMMENT 'HTTP状态码',
  `prompt_tokens` bigint NULL DEFAULT 0 COMMENT '提示词Token数',
  `completion_tokens` bigint NULL DEFAULT 0 COMMENT '完成Token数',
  `total_tokens` bigint NULL DEFAULT 0 COMMENT '总Token数',
  `duration_ms` bigint NULL DEFAULT 0 COMMENT '耗时(毫秒)',
  `risk_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'Clean' COMMENT '风险等级(Clean/Low/Medium/High/Critical)',
  `risk_score` int NULL DEFAULT 0 COMMENT '风险评分',
  `risk_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '风险摘要',
  `security_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'Allow' COMMENT '安全动作(Allow/Sanitize/Block)',
  `sanitized` tinyint NULL DEFAULT 0 COMMENT '是否已脱敏: 0=否 1=是',
  `blocked_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '阻断原因',
  `client_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户端IP',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '错误信息',
  `request_body` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '请求体',
  `response_choices` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '响应内容',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '链路追踪ID',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_seq`(`seq` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_api_key`(`api_key_id` ASC) USING BTREE,
  INDEX `idx_channel`(`channel_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1068 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '请求日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of request_logs
-- ----------------------------
INSERT INTO `request_logs` VALUES ('00eb51a2-0ffb-4890-8e2d-8e7e454fc4b1', 1045, '5ac0dfa8-c73d-4b31-92f7-4d7b43f97a5a', 'deepseek_api_key测试', 'ec90325f-552d-4ad7-aa89-b21975b43ef6', '测试-dd', 'deepseek-v4-flash', 'deepseek-v4-flash', 'completion', 'sse', 1, 0, 200, 43, 715, 758, 5693, 'Critical', 90, 'CRITICAL risk (score 90): 2 finding(s), actions={redact=2}, scanned 3 string(s), truncated=false', 'Sanitize', 1, NULL, NULL, NULL, '{\"model\":\"deepseek-v4-flash\",\"messages\":[{\"role\":\"user\",\"content\":\"你好 请问下面这个路径是什么 168.****.198\"}],\"temperature\":0.7,\"max_tokens\":1024,\"stream\":true}', '[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"你好，`168.****.198` 本身不是一个“路径”，更像是**被星号脱敏/隐藏过的 IPv4 地址片段**。\\n\\n正常 IPv4 地址应类似：\\n\\n```text\\n168.1.23.198\\n```\\n\\n也就是四段数字，每段 0–255。你写的 `168.****.198` 中间部分被隐藏了，所以仅凭这个**无法判断具体是哪台设备、哪个网站或哪个位置**。\\n\\n如果它其实是类似 `192.168.1.198`，那通常属于**局域网私有 IP**；如果是 `168.x.x.198`，则可能是公网 IP 地址。  \\n你可以把完整格式或出现场景（例如路由器、网址、文件路径、报错信息）发出来，我可以帮你更准确判断。\",\"reasoning_content\":\"We need answer Chinese. User asks \\\"你好 请问下面这个路径是什么 168.****.198\\\" maybe asks what path is 168.*.*.198? They say \\\"路径\\\" perhaps IP address. Need clarify. 168.****.198 looks like IP address with masked middle octets. Need explain could be IP address IPv4 format, but 168.x.x.198 (unless masked). Not a \\\"path\\\"; might be IP. If it\'s URL path? Could be part of IP address. Need ask context. Maybe concern security? Need say 仅凭这个无法定位/判断，168.198? Wait 168.****.198 has four parts? Actually \\\"168.****.198\\\" only 3 parts? The mask may include one octet? Let\'s parse: 168 . **** . 198 = three sections, with **** representing possibly one or more? IPv4 requires four numbers 0-255. If **** stands for two octets? Could be \\\"168.*.*.198\\\" (four parts) but they typed 168.****.198 with middle **** hiding two octets. Need mention.\\n\\nNeed provide examples: 168.1.1.198 is IPv4 address. If starts 168, first octet 168 (public? Actually 168.0.0.0/8 not private officially? 168.0.0.0 not reserved, public, though some used? IPv4 private ranges: 10/8, 172.16/12, 192.168/16; 168.x.x.x is public allocated. But without full address can\'t determine. 192.168.x.x is private. If it\'s \\\"168.****.198\\\" as file path? No.\\n\\nMaybe ask \\\"路径是什么\\\" could be URL path? Need answer: It\'s not a path,更像脱敏后的 IP 地址片段。请提供完整格式/上下文，我不能仅凭这个识别具体设备/地点. Also avoid guessing.\\n\\nNeed keep concise. Chinese. Maybe mention \\\"星号是通配/脱敏\\\". Final. \\nNeed perhaps \\\"168.****.198\\\" could be 168.0.0.198? But no. \\nNeed explain if it is \\\"168.192.198\\\"? No invalid due 3 octets. \\nCould state: 如果是完整地址应为 168.a.b.198，中间两段被 **** 隐藏. \\nPotential security: IP can\'t by itself identify exact person; public IP can approximate location. Private IP (e.g., 192.168.x.x) only internal LAN.\\n\\nLet\'s craft final with questions. \"},\"finish_reason\":\"stop\"}]', '8d2af5d7-7171-4831-a90f-9016b58dc46b', '2026-10-25T16:11:40.009792+08:00');
