INSERT INTO `security_builtin_rules` VALUES ('builtin-unicode_bidi', 'unicode_bidi', 'unicode', '双向控制字符', 'high', NULL, NULL, '双向控制字符', '检测 RTL/LTR 等双向文本控制字符', 'security.scan_unicode', 1, '2026-10-25T15:27:03.581801+08:00', '2026-10-25T16:51:24.652153+08:00');
INSERT INTO `security_builtin_rules` VALUES ('builtin-unicode_homoglyph', 'unicode_homoglyph', 'unicode', '同形字符混淆', 'medium', NULL, NULL, '同形字符混淆', '检测混合文字体系的同形字符伪装', 'security.scan_unicode', 1, '2026-10-25T15:27:03.581801+08:00', '2026-10-25T16:51:24.652153+08:00');
INSERT INTO `security_builtin_rules` VALUES ('builtin-unicode_pua', 'unicode_pua', 'unicode', '私用区字符', 'medium', NULL, NULL, '私用区字符', '检测 Unicode 私用区（PUA）字符', 'security.scan_unicode', 1, '2026-10-25T15:27:03.581801+08:00', '2026-10-25T16:51:24.652153+08:00');
INSERT INTO `security_builtin_rules` VALUES ('builtin-unicode_variation', 'unicode_variation', 'unicode', '变体选择符', 'medium', NULL, NULL, '变体选择符', '检测 Unicode 变体选择符', 'security.scan_unicode', 1, '2026-10-25T15:27:03.581801+08:00', '2026-10-25T16:51:24.652153+08:00');
INSERT INTO `security_builtin_rules` VALUES ('builtin-unicode_zero_width', 'unicode_zero_width', 'unicode', '零宽字符', 'medium', NULL, NULL, '零宽字符', '检测零宽空格、零宽连接符等 Unicode 隐写字符', 'security.scan_unicode', 1, '2026-10-25T15:27:03.581801+08:00', '2026-10-25T16:51:24.652153+08:00');

-- ----------------------------
-- Table structure for security_custom_rules
-- ----------------------------
DROP TABLE IF EXISTS `security_custom_rules`;
CREATE TABLE `security_custom_rules`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则ID',
  `rule_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规则类型(regex/keyword/semantic)',
  `category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '安全分类',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规则名称',
  `pattern` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '匹配模式/正则表达式',
  `severity` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '严重级别',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处置动作(Allow/Sanitize/Block)',
  `enabled` tinyint NULL DEFAULT 1 COMMENT '是否启用: 0=否 1=是',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '规则描述',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
  `updated_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '自定义安全规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of security_custom_rules
-- ----------------------------
