INSERT INTO `wiki_pages` VALUES ('002e83e0-ae32-4fcb-b88f-82db61476622', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/java-spring', 'Java与Spring优秀书籍推荐', 'note', '7f93e723', 308, 'books/db|点击查看数据库书籍推荐', 'title: Java与Spring优秀书籍推荐\npath: books/java-spring\ntags: [Java, Spring, 编程, 技术书籍]', 'Java, Spring, 编程, 技术书籍', 'active', '## Java/Spring推荐书籍\n\n### 1. 《Java虚拟机规范(Java SE 7)》 ⭐⭐⭐⭐\n\n适合深入了解JVM规范，内容专业但较为晦涩，建议有一定JVM基础后阅读。\n\n### 2. 《深入理解Java虚拟机：JVM高级特性与最佳实践（第3版）》 ⭐⭐⭐⭐\n\n经典JVM著作，从工作原理和工程实践两个维度剖析JVM，适合深入学习Java虚拟机。\n\n### 3. 《JAVA核心知识点整理》 ⭐⭐⭐⭐\n\n覆盖JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等核心知识点。\n\n### 4. 《On Java 8 编程思想》 ⭐⭐⭐⭐\n\nBruce Eckel著作，译者结合多种翻译资源及个人理解进行本地化，专业且言简意赅，适合深入学习Java 8。\n\n### 5. 《深入浅出Java多线程》 ⭐⭐⭐⭐\n\nRedSpider社区整理，系统讲解Java并发编程原理，适合提升并发编程能力。\n\n### 6. 《Java核心技术 I》 ⭐⭐⭐⭐\n\n详细讲解Java API及细节，适合深入了解Java对象序列化等底层知识。\n\n### 7. 《effective java 3》 ⭐⭐⭐⭐\n\n以条目形式组织内容，涉及软件设计多个方面，适合查阅和学习Java最佳实践。\n\n### 8. 《Java解惑》 ⭐⭐⭐\n\n列举Java细节问题，适合提升对Java异常情况的敏感度。\n\n### 9. 《Thinking In Java 4》 ⭐⭐⭐⭐⭐\n\n深入讲解Java技术，适合进阶学习。\n\n### 10. 《Java内存模型》 ⭐⭐⭐⭐\n\n系统讲解Java线程通信与内存模型，适合理解并发底层原理。\n\n### 11. 《Java并发编程实践》 ⭐⭐⭐⭐\n\n由并发工具创造者撰写，系统讲解并发构建块、性能优化、测试等内容。\n\n### 12. 《Spring揭秘》 ⭐⭐⭐⭐⭐\n\n国产良心技术书籍，深入讲解Spring框架设计理念、IOC、AOP等核心内容。\n\n### 13. 《Spring源码深度解析》 ⭐⭐⭐\n\n系统讲解Spring源码及设计理念，适合深入了解Spring内部机制。\n\n### 14. 《深入理解SpringCloud与微服务构建》 ⭐⭐⭐⭐\n\n介绍SpringBoot微框架设计理念、重点功能和模块，适合微服务架构学习。\n\n### 15. 《美团技术后台篇》 ⭐⭐⭐⭐\n\n美团点评高级技术汇总，涵盖字节码编程、全链路监控、分布式ID生成等核心技术。\n\n### 16. 《Java Concurrency in Practice》 ⭐⭐⭐⭐⭐\n\n全面讲解并发与线程安全、性能优化、测试等高级主题。\n\n### 17. 小傅哥的《手写MyBatis》 ⭐⭐⭐⭐⭐\n\n通过手写过程学习Mybatis核心功能实现，适合深入理解Mybatis源码。\n\n---\n\n[[books/db|点击查看数据库书籍推荐]]', '2026-08-09T13:36:02.188344+08:00', '2026-08-09T13:36:02.188344+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('05b4ef02-5e53-4e2a-bd6a-2fa6b18b116e', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/original-pdf', '技术号主原创书籍PDF', 'note', 'c59aab0d', 128, 'books/other-series|点击查看其他系列书籍推荐', 'title: 技术号主原创书籍PDF\npath: books/original-pdf\ntags: [原创书籍, PDF, 技术分享]', '原创书籍, PDF, 技术分享', 'active', '## 号主原创书籍[免费下载]\n\n### 1. 小傅哥的《字节码编程》 ⭐⭐⭐\n\n涵盖ASM、Javassist、Byte-budy三大字节码框架和JavaAgent使用，附带案例源码。\n\n### 2. 小傅哥的《重学 Java 设计模式》 ⭐⭐⭐⭐\n\n实战型Java编程资料，涵盖22个真实业务场景，适合提升设计模式实战能力。\n\n### 3. 《Java 基础核心总结》 ⭐⭐⭐\n\n适合Java初学者和其他语言转型程序员，内容广泛、语言简练。\n\n### 4. 《HTTP 超全汇总》 ⭐⭐⭐\n\n全面讲解HTTP协议内容，适合作为速查手册或培训教材。\n\n### 5. 《程序员必知的硬核知识大全》 ⭐⭐⭐⭐\n\n浓缩CPU、内存、二进制、计算机硬件、应用、算法精华知识，通俗易懂。\n\n### 6. 阿宝哥的《前端进阶篇》 ⭐⭐⭐\n\n涵盖Video播放器、图片处理、Word文档、混合加密、网络等前端专题内容。\n\n### 7. 阿宝哥的《重学TS》 ⭐⭐⭐⭐\n\n228页内容，包含TypeScript入门、设计模式、插件化架构、依赖注入等进阶内容。\n\n---\n\n[[books/other-series|点击查看其他系列书籍推荐]]', '2026-08-09T13:36:02.199889+08:00', '2026-08-09T13:36:02.199889+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('1eae0f40-9a15-443b-9acb-e6399045371c', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/architecture-design', '架构与设计优秀书籍推荐', 'note', '2c72c0e1', 115, 'books/original-pdf|点击查看号主原创书籍PDF', 'title: 架构与设计优秀书籍推荐\npath: books/architecture-design\ntags: [架构, 设计模式, 重构, 技术书籍]', '架构, 设计模式, 重构, 技术书籍', 'active', '## 架构&设计推荐书籍\n\n### 1. 《代码整洁之道》 ⭐⭐⭐⭐\n\n提出代码质量与整洁度成正比，提供整洁代码操作实践，适合提升代码质量。\n\n### 2. 《Head_First设计模式(中文版)》 ⭐⭐⭐⭐\n\n系统介绍多种设计模式及应用场景，适合学习设计模式与OO原则。\n\n### 3. 《编写可读代码的艺术》 ⭐⭐⭐\n\n强调代码对人的友好性和可读性，适合提升代码可读性。\n\n### 4. 《重构 改善既有代码的设计》 ⭐⭐⭐⭐\n\n介绍代码变换手法与重构动机，强调DRY原则和单一职责，适合学习重构技术。\n\n### 5. 《设计数据密集型应用 Designing Data Intensive Applications》 ⭐⭐⭐⭐\n\n深入分析大规模数据基础设施、分布式系统研究、一致性、可伸缩性、容错性等权衡，适合架构师阅读。\n\n### 6. 《企业应用架构模式》 ⭐⭐⭐⭐\n\n总结40多种企业应用解决方案模式，适合企业级应用架构学习。\n\n---\n\n[[books/original-pdf|点击查看号主原创书籍PDF]]', '2026-08-09T13:36:02.197069+08:00', '2026-08-09T13:36:02.197069+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('26bec2cb-20b4-425c-90f1-cdf1f9244f2f', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'star/overview', '星球介绍', 'note', 'c1c344a3', 360, '星球介绍,星球实战项目与技术内容', 'title: 星球介绍\npath: star/overview\ntags: [星球, 编程, 实战项目, 技术交流]', '星球, 编程, 实战项目, 技术交流', 'active', NULL, '2026-08-08T15:40:53.938702+08:00', '2026-08-08T16:10:29.864827+08:00', 'none', NULL, NULL);
INSERT INTO `wiki_pages` VALUES ('35060f48-f1d8-4070-bfc1-d342777561f3', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'pintuan/pintuan-table-design', '拼团库表设计', 'note', 'e198f4b4', 425, '拼团业务流程,拼团折扣策略设计,人群标签体系,拼团回调机制', 'title: 拼团库表设计\npath: pintuan/pintuan-table-design\ntags: [拼团, 数据库设计, 系统架构]', '拼团, 数据库设计, 系统架构', 'active', NULL, '2026-08-08T18:11:32.306989+08:00', '2026-08-08T18:11:32.306989+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('80700d74-d07b-440f-91a7-128ddc6211bc', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'xingqiu/overview', '星球介绍', 'note', 'fed0f18f', 370, '星球介绍', 'title: 星球介绍\npath: xingqiu/overview\ntags: [星球, 编程, 实战项目, 技术交流]', '星球, 编程, 实战项目, 技术交流', 'active', NULL, '2026-08-08T15:40:48.002505+08:00', '2026-08-08T15:59:11.983294+08:00', 'none', NULL, NULL);
INSERT INTO `wiki_pages` VALUES ('91256166-6aef-4de5-8e44-b71a8a43d780', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/redis', 'Redis优秀书籍推荐', 'note', 'eadda264', 72, 'books/architecture-design|点击查看架构与设计书籍推荐', 'title: Redis优秀书籍推荐\npath: books/redis\ntags: [Redis, 缓存, 运维, 技术书籍]', 'Redis, 缓存, 运维, 技术书籍', 'active', '## Redis推荐书籍\n\n### 1. 《Redis设计与实现》 ⭐⭐⭐⭐\n\n黄健宏著作，详细注释Redis 2.6和3.0源代码，适合深入学习Redis底层原理。\n\n### 2. 《Redis 深度历险：核心原理与应用实践》 ⭐⭐⭐⭐\n\n钱文品著作，内容涵盖基础与应用、原理、集群、拓展、源码五大块，适合系统学习Redis。\n\n### 3. 《Redis开发与运维》 ⭐⭐⭐⭐\n\n付磊、张益军著作，全面讲解Redis基本功能及应用，结合实际开发运维案例，适合提升运维能力。\n\n---\n\n[[books/architecture-design|点击查看架构与设计书籍推荐]]', '2026-08-09T13:36:02.194630+08:00', '2026-08-09T13:36:02.194630+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('9571c2f6-38ce-4e8c-9147-5800b6cd0f8d', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/other-series', '其他系列优秀书籍推荐', 'note', 'de21ca01', 172, 'books/humanity|点击查看人性相关书籍推荐', 'title: 其他系列优秀书籍推荐\npath: books/other-series\ntags: [综合书籍, 编程, 技术, 计算机]', '综合书籍, 编程, 技术, 计算机', 'active', '## 其他系列推荐书籍\n\n### 1. 《阿里工程师的自我修养》 ⭐⭐⭐⭐\n\n涵盖工程师成长、思维、技巧、经验复盘，适合提升个人能力。\n\n### 2. Java开发手册（嵩山版） ⭐⭐⭐⭐\n\n阿里巴巴团队编写，提炼集体编程经验和软件设计智慧，帮助开发者规范代码。\n\n### 3. 《Http权威指南》 ⭐⭐⭐⭐\n\n深入讲解HTTP协议，适合系统学习网络通信。\n\n### 4. Elasticsearch 权威指南 中文版 ⭐⭐⭐⭐\n\n介绍Elasticsearch基本概念、操作、结构化搜索、性能优化等内容。\n\n### 5. 计算机是怎样跑起来的(日)矢泽久雄 ⭐⭐⭐⭐⭐\n\n全面介绍计算机结构、编程、数据库、网络等内容。\n\n### 6. 编码：隐匿在计算机软硬件背后的语言 ⭐⭐⭐⭐⭐\n\n通俗易懂讲解计算机工作原理，适合深入理解计算机基础。\n\n### 7. 计算机程序的构造和解释(原书第2版) ⭐⭐⭐⭐⭐\n\nMIT教材，影响深远，适合学习程序设计系统。\n\n### 8. 代码大全（第2版） ⭐⭐⭐⭐⭐\n\n软件构建手册，涵盖软件质量、编程思想、技术、示例等内容。\n\n### 9. 编程匠艺 ⭐⭐⭐⭐\n\n涵盖代码风格、命名、错误处理、安全性、团队合作、开发过程等内容。\n\n### 10. Zookeeper 分布式过程 ⭐⭐⭐⭐\n\n系统讲解分布式系统、Zookeeper原理与应用。\n\n### 11. 黑客与画家 ⭐⭐⭐⭐\n\nPaul Graham文集，介绍黑客成长、编程语言、互联网行业规则等话题。\n\n---\n\n[[books/humanity|点击查看人性相关书籍推荐]]', '2026-08-09T13:36:02.201996+08:00', '2026-08-09T13:36:02.201996+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('b8a670ff-069f-4721-b3cf-6e547245e0ff', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/db', '数据库优秀书籍推荐', 'note', '2cf1268c', 73, 'books/redis|点击查看Redis书籍推荐', 'title: 数据库优秀书籍推荐\npath: books/db\ntags: [数据库, MySQL, 索引, 技术书籍]', '数据库, MySQL, 索引, 技术书籍', 'active', '## 数据库推荐书籍\n\n### 1. 《MySQL王者晋级之路》 ⭐⭐⭐⭐\n\n系统剖析MySQL体系结构、备份恢复、复制、高可用集群架构、优化、故障排查、新版本特性、监控、升级及技术面试宝典。\n\n### 2. 《数据库索引设计与优化》 ⭐⭐⭐⭐\n\n系统讲解关系型数据库访问路径、表和索引扫描方式、SQL性能优化等内容，适合深入理解索引设计。\n\n### 3. 《MYSQL技术内幕：INNODB存储引擎》 ⭐⭐⭐⭐\n\n深入介绍InnoDB存储引擎内核，从源代码角度解析体系结构、实现原理、工作机制，适合数据库开发者。\n\n---\n\n[[books/redis|点击查看Redis书籍推荐]]', '2026-08-09T13:36:02.192666+08:00', '2026-08-09T13:36:02.192666+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('c196b19d-1e40-48b9-bc9f-7ac11d3baa90', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/humanity', '人性与心灵建设书籍推荐', 'note', '593ea0f', 59, 'books/worth-reading|返回值得一看的好书推荐目录', 'title: 人性与心灵建设书籍推荐\npath: books/humanity\ntags: [人性, 心灵建设, 沟通, 软件开发]', '人性, 心灵建设, 沟通, 软件开发', 'active', '## 人性与心灵建设推荐书籍\n\n- 《非暴力沟通》(美)卢森堡\n- 《逆商：我们该如何应对坏事件》\n- 《超越自卑》阿德勒\n- 《关键对话-如何高效能沟通》\n- 《人月神话》  \n  经典著作，软件开发相关人员必读。\n\n---\n\n*以上PDF书籍链接皆来自网络分享，如涉及版权和付费等问题，请及时删除并购买正版书籍。本页仅作为宣传帮助作者推广，下载试读PDF后请及时删除并支持正版。*\n\n[[books/worth-reading|返回值得一看的好书推荐目录]]\n\n---', '2026-08-09T13:36:02.204039+08:00', '2026-08-09T13:36:02.204039+08:00', 'done', 'text-embedding-3-small', );
INSERT INTO `wiki_pages` VALUES ('d824afe4-654a-44b7-9baa-dfd545c1441c', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'books/worth-reading', '值得一看的好书推荐', 'note', '9d96881c', 270, 'books/general-recommendation|一、推荐,books/java-spring|二、Java/Spring,books/db|三、DB,books/redis|四、Redis,books/architecture-design|五、架构&设计,books/original-pdf|六、号主原创书籍[免费下载,books/other-series|七、其他系列,books/humanity|八、人性,books/java-spring|点击查看Java/Spring书籍推荐', 'title: 值得一看的好书推荐\npath: books/worth-reading\ntags: [书籍推荐, 技术书籍, 编程, 架构, 人性]', '书籍推荐, 技术书籍, 编程, 架构, 人性', 'active', ':seedling: **读不在三更五鼓，功只怕一曝十寒！**  \n**岁月从不辜负奋斗的人，愿努力拼搏学习的你，都能收获美好的前程！**\n\n- 承遇朝霞，年少正恰。\n- 整装戎马，刻印风华。\n\n# 目录\n\n- [[books/general-recommendation|一、推荐]]\n- [[books/java-spring|二、Java/Spring]]\n- [[books/db|三、DB]]\n- [[books/redis|四、Redis]]\n- [[books/architecture-design|五、架构&设计]]\n- [[books/original-pdf|六、号主原创书籍[免费下载]]]\n- [[books/other-series|七、其他系列]]\n- [[books/humanity|八、人性]]\n\n---\n\n## 一、推荐\n\n### 小傅哥的《重学 Java 设计模式》 ⭐⭐⭐⭐\n\n本书由小傅哥投入50天时间，从互联网实际业务开发中抽离出交易、营销、秒杀、中间件、源码等22个真实业务场景，编写了18万字271页的实战型Java编程资料。内容深入，适合提升Java设计模式实战能力。\n\n### 小傅哥的《Java 面经手册》 ⭐⭐⭐⭐\n\n全书共计5章29节，417页11.5万字，涵盖数据结构、算法逻辑、并发编程、JVM以及简历和互联网大厂面试等内容。每一章节都配有实践验证的源码，适合系统学习Java核心技术。\n\n### 小傅哥的《字节码编程》 ⭐⭐⭐\n\n全书共计107页，11万7千字，涵盖ASM、Javassist、Byte-budy三大字节码框架和JavaAgent使用，附带整套案例源码，适合深入了解Java字节码。\n\n### 《JAVA核心知识点整理》 ⭐⭐⭐⭐\n\n整理了JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等大量知识点，适合系统复习Java核心内容。\n\n### 计算机是怎样跑起来的(日)矢泽久雄 ⭐⭐⭐⭐⭐\n\n以图配文，介绍计算机结构、手工汇编、程序流程、算法、数据结构、面向对象编程、数据库、TCP/IP网络、数据加密、XML、计算机系统开发以及SE相关知识，适合全面了解计算机原理。\n\n### cxuan的《程序员必知的硬核知识大全》 ⭐⭐⭐⭐\n\n浓缩了CPU、内存、二进制、计算机硬件、应用、算法的精华知识，以通俗易懂的形式讲解，适合程序员夯实基础。\n\n---\n\n[[books/java-spring|点击查看Java/Spring书籍推荐]]', '2026-08-09T13:36:02.184954+08:00', '2026-08-09T13:36:02.184954+08:00', 'done', 'text-embedding-3-small', );

-- ----------------------------
-- Table structure for wiki_pages_fts
-- ----------------------------
DROP TABLE IF EXISTS `wiki_pages_fts`;
CREATE TABLE `wiki_pages_fts`  (
  `page_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面ID',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `title` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路径',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '内容',
  `tags` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签',
  PRIMARY KEY (`page_id`) USING BTREE,
  INDEX `idx_project_id`(`project_id` ASC) USING BTREE,
  FULLTEXT INDEX `ft_title_content`(`title`, `content`, `tags`) WITH PARSER `ngram`
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Wiki页面全文搜索表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wiki_pages_fts
-- ----------------------------
INSERT INTO `wiki_pages_fts` VALUES ('002e83e0-ae32-4fcb-b88f-82db61476622', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'Java与Spring优秀书籍推荐', 'books/java-spring', '## Java/Spring推荐书籍\n\n### 1. 《Java虚拟机规范(Java SE 7)》 ⭐⭐⭐⭐\n\n适合深入了解JVM规范，内容专业但较为晦涩，建议有一定JVM基础后阅读。\n\n### 2. 《深入理解Java虚拟机：JVM高级特性与最佳实践（第3版）》 ⭐⭐⭐⭐\n\n经典JVM著作，从工作原理和工程实践两个维度剖析JVM，适合深入学习Java虚拟机。\n\n### 3. 《JAVA核心知识点整理》 ⭐⭐⭐⭐\n\n覆盖JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等核心知识点。\n\n### 4. 《On Java 8 编程思想》 ⭐⭐⭐⭐\n\nBruce Eckel著作，译者结合多种翻译资源及个人理解进行本地化，专业且言简意赅，适合深入学习Java 8。\n\n### 5. 《深入浅出Java多线程》 ⭐⭐⭐⭐\n\nRedSpider社区整理，系统讲解Java并发编程原理，适合提升并发编程能力。\n\n### 6. 《Java核心技术 I》 ⭐⭐⭐⭐\n\n详细讲解Java API及细节，适合深入了解Java对象序列化等底层知识。\n\n### 7. 《effective java 3》 ⭐⭐⭐⭐\n\n以条目形式组织内容，涉及软件设计多个方面，适合查阅和学习Java最佳实践。\n\n### 8. 《Java解惑》 ⭐⭐⭐\n\n列举Java细节问题，适合提升对Java异常情况的敏感度。\n\n### 9. 《Thinking In Java 4》 ⭐⭐⭐⭐⭐\n\n深入讲解Java技术，适合进阶学习。\n\n### 10. 《Java内存模型》 ⭐⭐⭐⭐\n\n系统讲解Java线程通信与内存模型，适合理解并发底层原理。\n\n### 11. 《Java并发编程实践》 ⭐⭐⭐⭐\n\n由并发工具创造者撰写，系统讲解并发构建块、性能优化、测试等内容。\n\n### 12. 《Spring揭秘》 ⭐⭐⭐⭐⭐\n\n国产良心技术书籍，深入讲解Spring框架设计理念、IOC、AOP等核心内容。\n\n### 13. 《Spring源码深度解析》 ⭐⭐⭐\n\n系统讲解Spring源码及设计理念，适合深入了解Spring内部机制。\n\n### 14. 《深入理解SpringCloud与微服务构建》 ⭐⭐⭐⭐\n\n介绍SpringBoot微框架设计理念、重点功能和模块，适合微服务架构学习。\n\n### 15. 《美团技术后台篇》 ⭐⭐⭐⭐\n\n美团点评高级技术汇总，涵盖字节码编程、全链路监控、分布式ID生成等核心技术。\n\n### 16. 《Java Concurrency in Practice》 ⭐⭐⭐⭐⭐\n\n全面讲解并发与线程安全、性能优化、测试等高级主题。\n\n### 17. 小傅哥的《手写MyBatis》 ⭐⭐⭐⭐⭐\n\n通过手写过程学习Mybatis核心功能实现，适合深入理解Mybatis源码。\n\n---\n\n[[books/db|点击查看数据库书籍推荐]]', 'Java, Spring, 编程, 技术书籍');
INSERT INTO `wiki_pages_fts` VALUES ('05b4ef02-5e53-4e2a-bd6a-2fa6b18b116e', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '技术号主原创书籍PDF', 'books/original-pdf', '## 号主原创书籍[免费下载]\n\n### 1. 小傅哥的《字节码编程》 ⭐⭐⭐\n\n涵盖ASM、Javassist、Byte-budy三大字节码框架和JavaAgent使用，附带案例源码。\n\n### 2. 小傅哥的《重学 Java 设计模式》 ⭐⭐⭐⭐\n\n实战型Java编程资料，涵盖22个真实业务场景，适合提升设计模式实战能力。\n\n### 3. 《Java 基础核心总结》 ⭐⭐⭐\n\n适合Java初学者和其他语言转型程序员，内容广泛、语言简练。\n\n### 4. 《HTTP 超全汇总》 ⭐⭐⭐\n\n全面讲解HTTP协议内容，适合作为速查手册或培训教材。\n\n### 5. 《程序员必知的硬核知识大全》 ⭐⭐⭐⭐\n\n浓缩CPU、内存、二进制、计算机硬件、应用、算法精华知识，通俗易懂。\n\n### 6. 阿宝哥的《前端进阶篇》 ⭐⭐⭐\n\n涵盖Video播放器、图片处理、Word文档、混合加密、网络等前端专题内容。\n\n### 7. 阿宝哥的《重学TS》 ⭐⭐⭐⭐\n\n228页内容，包含TypeScript入门、设计模式、插件化架构、依赖注入等进阶内容。\n\n---\n\n[[books/other-series|点击查看其他系列书籍推荐]]', '原创书籍, PDF, 技术分享');
INSERT INTO `wiki_pages_fts` VALUES ('1eae0f40-9a15-443b-9acb-e6399045371c', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '架构与设计优秀书籍推荐', 'books/architecture-design', '## 架构&设计推荐书籍\n\n### 1. 《代码整洁之道》 ⭐⭐⭐⭐\n\n提出代码质量与整洁度成正比，提供整洁代码操作实践，适合提升代码质量。\n\n### 2. 《Head_First设计模式(中文版)》 ⭐⭐⭐⭐\n\n系统介绍多种设计模式及应用场景，适合学习设计模式与OO原则。\n\n### 3. 《编写可读代码的艺术》 ⭐⭐⭐\n\n强调代码对人的友好性和可读性，适合提升代码可读性。\n\n### 4. 《重构 改善既有代码的设计》 ⭐⭐⭐⭐\n\n介绍代码变换手法与重构动机，强调DRY原则和单一职责，适合学习重构技术。\n\n### 5. 《设计数据密集型应用 Designing Data Intensive Applications》 ⭐⭐⭐⭐\n\n深入分析大规模数据基础设施、分布式系统研究、一致性、可伸缩性、容错性等权衡，适合架构师阅读。\n\n### 6. 《企业应用架构模式》 ⭐⭐⭐⭐\n\n总结40多种企业应用解决方案模式，适合企业级应用架构学习。\n\n---\n\n[[books/original-pdf|点击查看号主原创书籍PDF]]', '架构, 设计模式, 重构, 技术书籍');
INSERT INTO `wiki_pages_fts` VALUES ('26bec2cb-20b4-425c-90f1-cdf1f9244f2f', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '星球介绍', 'star/overview', NULL, '星球, 编程, 实战项目, 技术交流');
