INSERT INTO `wiki_pages_fts` VALUES ('80700d74-d07b-440f-91a7-128ddc6211bc', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '星球介绍', 'xingqiu/overview', NULL, '星球, 编程, 实战项目, 技术交流');
INSERT INTO `wiki_pages_fts` VALUES ('91256166-6aef-4de5-8e44-b71a8a43d780', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'Redis优秀书籍推荐', 'books/redis', '## Redis推荐书籍\n\n### 1. 《Redis设计与实现》 ⭐⭐⭐⭐\n\n黄健宏著作，详细注释Redis 2.6和3.0源代码，适合深入学习Redis底层原理。\n\n### 2. 《Redis 深度历险：核心原理与应用实践》 ⭐⭐⭐⭐\n\n钱文品著作，内容涵盖基础与应用、原理、集群、拓展、源码五大块，适合系统学习Redis。\n\n### 3. 《Redis开发与运维》 ⭐⭐⭐⭐\n\n付磊、张益军著作，全面讲解Redis基本功能及应用，结合实际开发运维案例，适合提升运维能力。\n\n---\n\n[[books/architecture-design|点击查看架构与设计书籍推荐]]', 'Redis, 缓存, 运维, 技术书籍');
INSERT INTO `wiki_pages_fts` VALUES ('9571c2f6-38ce-4e8c-9147-5800b6cd0f8d', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '其他系列优秀书籍推荐', 'books/other-series', '## 其他系列推荐书籍\n\n### 1. 《阿里工程师的自我修养》 ⭐⭐⭐⭐\n\n涵盖工程师成长、思维、技巧、经验复盘，适合提升个人能力。\n\n### 2. Java开发手册（嵩山版） ⭐⭐⭐⭐\n\n阿里巴巴团队编写，提炼集体编程经验和软件设计智慧，帮助开发者规范代码。\n\n### 3. 《Http权威指南》 ⭐⭐⭐⭐\n\n深入讲解HTTP协议，适合系统学习网络通信。\n\n### 4. Elasticsearch 权威指南 中文版 ⭐⭐⭐⭐\n\n介绍Elasticsearch基本概念、操作、结构化搜索、性能优化等内容。\n\n### 5. 计算机是怎样跑起来的(日)矢泽久雄 ⭐⭐⭐⭐⭐\n\n全面介绍计算机结构、编程、数据库、网络等内容。\n\n### 6. 编码：隐匿在计算机软硬件背后的语言 ⭐⭐⭐⭐⭐\n\n通俗易懂讲解计算机工作原理，适合深入理解计算机基础。\n\n### 7. 计算机程序的构造和解释(原书第2版) ⭐⭐⭐⭐⭐\n\nMIT教材，影响深远，适合学习程序设计系统。\n\n### 8. 代码大全（第2版） ⭐⭐⭐⭐⭐\n\n软件构建手册，涵盖软件质量、编程思想、技术、示例等内容。\n\n### 9. 编程匠艺 ⭐⭐⭐⭐\n\n涵盖代码风格、命名、错误处理、安全性、团队合作、开发过程等内容。\n\n### 10. Zookeeper 分布式过程 ⭐⭐⭐⭐\n\n系统讲解分布式系统、Zookeeper原理与应用。\n\n### 11. 黑客与画家 ⭐⭐⭐⭐\n\nPaul Graham文集，介绍黑客成长、编程语言、互联网行业规则等话题。\n\n---\n\n[[books/humanity|点击查看人性相关书籍推荐]]', '综合书籍, 编程, 技术, 计算机');
INSERT INTO `wiki_pages_fts` VALUES ('b8a670ff-069f-4721-b3cf-6e547245e0ff', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '数据库优秀书籍推荐', 'books/db', '## 数据库推荐书籍\n\n### 1. 《MySQL王者晋级之路》 ⭐⭐⭐⭐\n\n系统剖析MySQL体系结构、备份恢复、复制、高可用集群架构、优化、故障排查、新版本特性、监控、升级及技术面试宝典。\n\n### 2. 《数据库索引设计与优化》 ⭐⭐⭐⭐\n\n系统讲解关系型数据库访问路径、表和索引扫描方式、SQL性能优化等内容，适合深入理解索引设计。\n\n### 3. 《MYSQL技术内幕：INNODB存储引擎》 ⭐⭐⭐⭐\n\n深入介绍InnoDB存储引擎内核，从源代码角度解析体系结构、实现原理、工作机制，适合数据库开发者。\n\n---\n\n[[books/redis|点击查看Redis书籍推荐]]', '数据库, MySQL, 索引, 技术书籍');
INSERT INTO `wiki_pages_fts` VALUES ('c196b19d-1e40-48b9-bc9f-7ac11d3baa90', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '人性与心灵建设书籍推荐', 'books/humanity', '## 人性与心灵建设推荐书籍\n\n- 《非暴力沟通》(美)卢森堡\n- 《逆商：我们该如何应对坏事件》\n- 《超越自卑》阿德勒\n- 《关键对话-如何高效能沟通》\n- 《人月神话》  \n  经典著作，软件开发相关人员必读。\n\n---\n\n*以上PDF书籍链接皆来自网络分享，如涉及版权和付费等问题，请及时删除并购买正版书籍。本页仅作为宣传帮助作者推广，下载试读PDF后请及时删除并支持正版。*\n\n[[books/worth-reading|返回值得一看的好书推荐目录]]\n\n---', '人性, 心灵建设, 沟通, 软件开发');
INSERT INTO `wiki_pages_fts` VALUES ('d824afe4-654a-44b7-9baa-dfd545c1441c', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', '值得一看的好书推荐', 'books/worth-reading', ':seedling: **读不在三更五鼓，功只怕一曝十寒！**  \n**岁月从不辜负奋斗的人，愿努力拼搏学习的你，都能收获美好的前程！**\n\n- 承遇朝霞，年少正恰。\n- 整装戎马，刻印风华。\n\n# 目录\n\n- [[books/general-recommendation|一、推荐]]\n- [[books/java-spring|二、Java/Spring]]\n- [[books/db|三、DB]]\n- [[books/redis|四、Redis]]\n- [[books/architecture-design|五、架构&设计]]\n- [[books/original-pdf|六、号主原创书籍[免费下载]]]\n- [[books/other-series|七、其他系列]]\n- [[books/humanity|八、人性]]\n\n---\n\n## 一、推荐\n\n### 小傅哥的《重学 Java 设计模式》 ⭐⭐⭐⭐\n\n本书由小傅哥投入50天时间，从互联网实际业务开发中抽离出交易、营销、秒杀、中间件、源码等22个真实业务场景，编写了18万字271页的实战型Java编程资料。内容深入，适合提升Java设计模式实战能力。\n\n### 小傅哥的《Java 面经手册》 ⭐⭐⭐⭐\n\n全书共计5章29节，417页11.5万字，涵盖数据结构、算法逻辑、并发编程、JVM以及简历和互联网大厂面试等内容。每一章节都配有实践验证的源码，适合系统学习Java核心技术。\n\n### 小傅哥的《字节码编程》 ⭐⭐⭐\n\n全书共计107页，11万7千字，涵盖ASM、Javassist、Byte-budy三大字节码框架和JavaAgent使用，附带整套案例源码，适合深入了解Java字节码。\n\n### 《JAVA核心知识点整理》 ⭐⭐⭐⭐\n\n整理了JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等大量知识点，适合系统复习Java核心内容。\n\n### 计算机是怎样跑起来的(日)矢泽久雄 ⭐⭐⭐⭐⭐\n\n以图配文，介绍计算机结构、手工汇编、程序流程、算法、数据结构、面向对象编程、数据库、TCP/IP网络、数据加密、XML、计算机系统开发以及SE相关知识，适合全面了解计算机原理。\n\n### cxuan的《程序员必知的硬核知识大全》 ⭐⭐⭐⭐\n\n浓缩了CPU、内存、二进制、计算机硬件、应用、算法的精华知识，以通俗易懂的形式讲解，适合程序员夯实基础。\n\n---\n\n[[books/java-spring|点击查看Java/Spring书籍推荐]]', '书籍推荐, 技术书籍, 编程, 架构, 人性');

-- ----------------------------
-- Table structure for wiki_projects
-- ----------------------------
DROP TABLE IF EXISTS `wiki_projects`;
CREATE TABLE `wiki_projects`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目描述',
  `status` int NULL DEFAULT 1 COMMENT '状态: 0=禁用 1=启用',
  `schema_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目schema定义',
  `wiki_dir` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'wiki' COMMENT 'wiki目录名',
  `ingest_model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'gpt-4.1' COMMENT '摄入模型',
  `chat_model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'gpt-4.1' COMMENT '对话模型',
  `ingest_channel_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摄入渠道ID',
  `chat_channel_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对话渠道ID',
  `mcp_enabled` int NULL DEFAULT 0 COMMENT 'MCP启用: 0=否 1=是',
  `source_count` int NULL DEFAULT 0 COMMENT '来源数量',
  `page_count` int NULL DEFAULT 0 COMMENT '页面数量',
  `last_ingest_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后摄入时间',
  `last_lint_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后检查时间',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
  `updated_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Wiki项目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wiki_projects
-- ----------------------------
INSERT INTO `wiki_projects` VALUES ('ffdac017-0ec6-4097-b28b-745ef9795a0e', '拼团', '', 1, NULL, 'wiki', 'gpt-4.1', 'gpt-4.1', NULL, NULL, 0, 3, 11, '2026-08-09T13:35:40.202970+08:00', NULL, '2026-08-08T15:33:53.434403+08:00', '2026-08-09 13:36:02');

-- ----------------------------
-- Table structure for wiki_sessions
-- ----------------------------
DROP TABLE IF EXISTS `wiki_sessions`;
CREATE TABLE `wiki_sessions`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色: user/assistant',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容',
  `sources_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '引用来源JSON',
  `model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '使用模型',
  `tokens_used` bigint NULL DEFAULT 0 COMMENT 'token使用量',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_id`(`project_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Wiki对话历史表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wiki_sessions
-- ----------------------------
INSERT INTO `wiki_sessions` VALUES ('178be696-68c1-4bd3-b8a1-ef5854148de0', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'user', '图书', NULL, 'gpt-4.1', 0, '2026-08-09T13:40:40.973145+08:00');
INSERT INTO `wiki_sessions` VALUES ('19859b03-28a1-49a7-b0e2-095f948bcb2f', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'assistant', '# 图书推荐\n\n根据 Wiki 页面内容，以下是各类优秀书籍的推荐目录，涵盖了编程、架构设计、数据库、计算机基础、人性与心灵建设等多个领域：\n\n---\n\n## 1. 值得一看的好书推荐\n\n- **《重学 Java 设计模式》**：实战型Java编程资料，适合提升设计模式能力\n- **《Java 面经手册》**：涵盖数据结构、算法、并发、JVM、面试等内容\n- **《字节码编程》**：深入讲解ASM、Javassist、Byte-budy等字节码框架\n- **《JAVA核心知识点整理》**：系统整理JVM、并发、Spring、微服务等知识\n\n详细目录请见「值得一看的好书推荐」页面  \n参考：[books/worth-reading]\n\n---\n\n## 2. Java与Spring优秀书籍推荐\n\n- **《Java虚拟机规范(Java SE 7)》**、**《深入理解Java虚拟机》**：深入学习JVM\n- **《On Java 8 编程思想》**、**《Thinking In Java 4》**：Java进阶学习\n- **《effective java 3》**、**《Java并发编程实践》**：Java最佳实践与并发编程\n- **《Spring实战》**等：Spring框架学习\n\n详细书目请见「Java与Spring优秀书籍推荐」页面  \n参考：[books/java-spring]\n\n---\n\n## 3. 架构与设计优秀书籍推荐\n\n- **《代码整洁之道》**、**《重构 改善既有代码的设计》**：提升代码质量与重构能力\n- **《Head_First设计模式》**：系统学习设计模式\n- **《设计数据密集型应用》**、**《企业应用架构模式》**：分布式系统与企业级架构\n\n详细书目请见「架构与设计优秀书籍推荐」页面  \n参考：[books/architecture-design]\n\n---\n\n## 4. 其他系列优秀书籍推荐\n\n- **《阿里工程师的自我修养》**、**Java开发手册（嵩山版）**：工程师成长与规范\n- **《Http权威指南》**、**Elasticsearch 权威指南**：网络与搜索引擎\n- **《计算机是怎样跑起来的》**、**《编码》**：计算机基础原理\n- **《代码大全》**、**《编程匠艺》**：软件开发与编程思想\n- **《Zookeeper 分布式过程》**、**《黑客与画家》**：分布式系统与互联网思考\n\n详细书目请见「其他系列优秀书籍推荐」页面  \n参考：[books/other-series]\n\n---\n\n## 5. 人性与心灵建设书籍推荐\n\n- **《非暴力沟通》**、**《逆商》**、**《超越自卑》**、**《关键对话》**：沟通与心理成长\n- **《人月神话》**：软件开发相关人员必读\n\n详细书目请见「人性与心灵建设书籍推荐」页面  \n参考：[books/humanity]\n\n---\n\n如需某一领域或具体书籍的详细介绍，请补充说明。', 'books/worth-reading,books/other-series,books/java-spring,books/humanity,books/architecture-design,xingqiu/overview,star/overview', 'gpt-4.1', 0, '2026-08-09T13:40:40.976841+08:00');
INSERT INTO `wiki_sessions` VALUES ('36932eb7-5e19-4c7d-82bd-8a37333b675a', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'assistant', '## 拼团简介\n\n根据当前提供的 Wiki 页面内容，关于“拼团”本身的详细介绍尚未直接给出。不过，从页面结构来看，拼团是一个项目，其核心内容涉及拼团相关的数据库表设计（参考：pintuan/pintuan-table-design）。\n\n### 1. 拼团的基本概念\n\n由于页面内容未直接说明拼团的定义，这里仅能根据常规理解和页面结构推测：  \n拼团通常指用户通过发起或参与团购活动，以较低价格购买商品或服务的一种电商促销方式。具体实现和业务逻辑需参考项目的详细设计文档。\n\n### 2. 拼团的数据库表设计\n\n页面「拼团库表设计」(pintuan/pintuan-table-design) 可能包含了拼团功能实现所需的数据库表结构，但当前内容未展示具体字段或表结构信息。\n\n### 3. 相关拓展\n\n目前没有直接关联的“拼团”业务说明或流程介绍。如果你需要拼团的详细业务流程、功能说明或数据库表结构，请补充更具体的问题或提供更详细的页面内容。\n\n---\n\n**总结**：  \n- 当前 Wiki 页面仅显示了“拼团库表设计”页面的存在，未提供具体内容。\n- 若需拼团的详细定义、业务流程或数据库结构，请补充相关页面内容或提出具体需求。\n\n**参考页面**：  \n- pintuan/pintuan-table-design\n\n如需进一步了解，请补充更详细的问题或页面内容。', 'pintuan/pintuan-table-design,xingqiu/overview,star/overview', 'gpt-4.1', 0, '2026-08-09T13:13:23.817540+08:00');
