-- ----------------------------
-- Table structure for wiki_sources
-- ----------------------------
DROP TABLE IF EXISTS `wiki_sources`;
CREATE TABLE `wiki_sources`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源ID',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'file' COMMENT '来源类型: file/url/text',
  `filename` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名',
  `file_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件路径',
  `source_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源URL',
  `content_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内容SHA256',
  `file_size` bigint NULL DEFAULT 0 COMMENT '文件大小',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'pending' COMMENT '状态: pending/ingesting/ready/error',
  `page_count` int NULL DEFAULT 0 COMMENT '生成页面数',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '错误信息',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
  `ingested_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摄入时间',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '来源原始内容',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_id`(`project_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Wiki来源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wiki_sources
-- ----------------------------
INSERT INTO `wiki_sources` VALUES ('a536d25a-738b-4a20-b417-edb1dbff261e', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'file', '第1-2节：拼团库表设计.md', NULL, NULL, NULL, NULL, 'ready', 1, NULL, '2026-08-08T18:11:17.988368+08:00', '2026-08-08 18:11:32', '# 《拼团交易平台系统》第1-2节：拼团库表设计\n\n- **本章难度**：★★★☆☆\n- **本章重点**：通过拼团业务，讲解拼团流程实现中，所需的库表结构。包括；运营视角的配置诉求、用户视角的使用诉求。\n- **课程视频**：[https://t.zsxq.com/iteVm](https://t.zsxq.com/iteVm)\n\n---\n\n**版权说明**：©本项目与星球签约合作，受[《中华人民共和国著作权法实施条例》](https://www.gov.cn/gongbao/content/2013/content_2339485.htm) 版权法保护，禁止任何理由和任何方式公开(public)源码、资料、视频等小傅哥发布的星球内容到Github、Gitee等各类平台，违反可追究进一步的法律责任。\n\n作者：小傅哥\n<br/>博客：[https://bugstack.cn](https://bugstack.cn)\n\n>沉淀、分享、成长，让自己和他人都能有所收获！😄\n\n大家好，我是技术UP主小傅哥。\n\n编程的代码是对数据逻辑的呈现，数据流转调度的好坏来自于数据结构设计的是否合理。而库表的设计就是对你过往学习数据结构知识的检测。\n\n在库表设计时你需要了解整个业务执行过程，在这些过程中需要哪些数据作为支撑。合理的数据结构的库表设计，会让你的系统逻辑实现容易被人理解。反之，你可能要做大量的代码处理，也就是算法过程复杂度会变得很高。\n\n这块知识的积累，最佳的手段就是多做实际的项目。从库表设计到编码实现，从编码实现反推库表合理性。做的多了，自然也就懂了。\n\n## 一、本章诉求\n\n通过拼团业务，讲解拼团流程实现中，所需的库表结构。包括；运营视角的配置诉求、用户视角的使用诉求。\n\n只要你可以看懂库表设计，基本你也可以了解整个业务系统是如何实现的了。有了这样的积累，进入公司接触新的项目时，可以先从库表进行了解。知道它们的流转关系，之后在看系统设计和代码实现会更加清晰。\n\n## 二、库表关系\n\n在设计一套库表时，需要根据业务流程划分出大块的功能区，知道这些功能区的流转关系。\n\n<div align=\"center\">\n    <img src=\"https://bugstack.cn/images/article/project/group-buy-market/group-buy-market-1-2-01.png\" width=\"650px\">\n</div>\n\n- 首先，站在运营的角度，要为这次拼团配置对应的拼团活动。那么就会涉及到；给哪个渠道的什么商品ID配置拼团，这样用户在进入商品页就可以看到带有拼团商品的信息了。之后要考虑，这个拼团的商品所提供的规则信息，包括；折扣、时间、人数等。还要拿到折扣的一个试算金额。这个试算出来的金额，就是告诉用户，通过拼团可以拿到的最低价格。\n- 之后，站在用户的角度，是参与拼团。首次发起一个拼团与参与已存在的拼团进行数据的记录，达成拼团约定拼团人数后，开始进行通知。这个通知的设计站在平台角度可以提供回调，那么任何的系统也就都可以接入了。\n- 另外，为了支撑这套库表，也会有人群的设计。人群是互联网公司中非常常用的手段，比如要把所有符合某个条件的用户ID，全部写入到一个特定的 Redis 记录中，之后就可以专门为这些人做特定的拼团活动了。\n- 那么，拼团活动表，为什么会把折扣拆分出来呢。因为这里的折扣可能有多种迭代到一个拼团上。比如，给一个商品添加了直减10元的优惠，又对符合的人群id的用户，额外打9折，这样就有了2个折扣迭代。所以拆分出来会更好维护。这是对常变的元素和稳定的元素进行设计的思考。\n\n>你可以先尝试按照这样的分析进行库表设计，之后在看下文的内容。\n\n## 三、库表设计\n\n### 1. 拼团配置表\n\n<div align=\"center\">\n    <img src=\"https://bugstack.cn/images/article/project/group-buy-market/group-buy-market-1-2-02.png\" width=\"650px\">\n</div>\n\n如图，详细设计表；拼团活动表、折扣配置表、人群标签表、人群标签任务表、人群标签明细表。\n\n- 拼团活动表：设定了拼团的成团规则，人群标签的使用可以限定哪些人可见，哪些人可参与。\n- 折扣配置表：拆分出拼团优惠到一个新的表进行多条配置。如果折扣还有更多的复杂规则，则可以配置新的折扣规则表进行处理。\n- 人群标签表：专门来做人群设计记录的，这3张表就是为了把符合规则的人群ID，也就是用户ID，全部跑任务到一个记录下进行使用。比如黑玫瑰人群、高净值人群、拼团履约率90%以上的人群等。\n\n### 2. 参与拼团表\n\n<div align=\"center\">\n    <img src=\"https://bugstack.cn/images/article/project/group-buy-market/group-buy-market-1-2-03.png\" width=\"650px\">\n</div>\n如图，详细设计表；拼团账户表、用户拼单表、用户拼单明细、回调任务表。\n\n- 拼团账户表：记录用户的拼团参与数据，一个是为了限制用户的参与拼团次数，另外是为了人群标签任务统计数据。\n- 用户拼单表：当有用户发起首次拼单的时候，产生拼单id，并记录所需成团的拼单记录，另外是写上拼团的状态、唯一索引、回调接口等。这样拼团完成就可以回调对接的平台，通知完成了。【微信支付也是这样的设计，回调支付结果，这样的设计可以方便平台化对接】当再有用户参与后，则写入用户拼单明细表。直至达成拼团。\n- 回调任务表：当拼团完成后，要做回调处理。但可能会有失败，所以加入任务的方式进行补偿。如果仍然失败，则需要对接的平台，自己查询拼团结果。\n\n## 四、读者作业\n\n- 简单作业：理解本节的拼团库表设计，理解每个字段的作用。把这些学习的内容在课程目录下点【写作业】，完成后，把你的作业链接放到本节的评论区。\n- 复杂作业：思考这里的各类规则后续应该怎么编码实现，比如组合模式、easyRule、drools，这些内容可以检索了解，以及系统上该如何实现，并提交作业。\n');
INSERT INTO `wiki_sources` VALUES ('b8b2ddfe-5d9e-48a6-9994-eddf5af45ddc', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'file', '星球介绍信息.md', NULL, NULL, NULL, NULL, 'ready', 1, NULL, '2026-08-08T15:40:33.133290+08:00', '2026-08-08 16:10:29', '🧑‍💻 带你学习，(23个+) 实战项目。提高编程思维，锻炼编码能力，增强简历竞争力！\n\n💪 一线互联网大厂架构师（小傅哥，13年+）亲自运营维护。注意⚠️ IOS 苹果用户请在公众号「bugstack虫洞栈」回复「星球」加入/续费。\n\n星球提供：基础教程、环境配置（避免用户浪费时间）、实战项目（循序渐进，进阶学习）、问题解答、就业指导、简历评审等各项服务。我会把自己在互联网大厂13+年的职业生涯（晋升到码农职业最顶部），技术经验等，分享给你。让你少走弯路，夯实能力，快速提高自己。\n\nhttps://bugstack.cn - 👣可进入【实战项目】，预览课程详细信息。\n\n🌍加入星球，你将获得以下权益（完整AI进阶路线）：\n\n项目学习：WaLiAPI（local gateway + rag）、AI Coding/DevOps 可持续交付助手（walicode、walissh）、AI MCP 网关、AI Agent（脚手架 + 场景应用）、AI Agent（拖拉拽 + 动态配置） 拼团交易系统（拼多多 C 端场景）、小型支付商城 (双架构开发)、大营销（超级大课）、OpenAI 应用、Lottery 分布式抽奖秒杀项目【含上百个面试题】、Api 网关 - 所有大厂都需要的项目、IM 通信系统 - Netty 实战应用、OpenAi 大模型应用服务项目、SpringBoot Starter 中间件设计和开发、动态线程池、支付 SDK、透视业务监控、OpenAi 代码评审、通用技术组件、本地消息组件等。\n\n手撕源码：手写 Mybatis，从零手写源码级复杂项目，提升架构思维，锻炼编码能力。\n\n技术小册：IDEA Plugin 开发手册、Java 面经手册、字节码编程、程序员数学、DDD 小册、分布式技术栈等。\n\n就业指导：可以在发送你的简历到我的邮箱 (见使用介绍)，提供简历批阅服务。同时提供相关就业辅导和未来发展指引。\n\n小傅哥的知识星球满是技术交流，无灌水、无拼凑，1v1 指导学习📖。加入星球的用户，小傅哥会把你拉入专属的星球 VIP 交流群。\n');
INSERT INTO `wiki_sources` VALUES ('e380a4c9-9333-462c-906f-35611dda3f04', 'ffdac017-0ec6-4097-b28b-745ef9795a0e', 'file', '值得一看的好书.md', NULL, NULL, NULL, NULL, 'ready', 8, NULL, '2026-08-09T13:35:40.172158+08:00', '2026-08-09 13:36:02', ':seedling: **`读不在三更五鼓，功只怕一曝十寒！`** **岁月从不辜负奋斗的人，愿努力拼搏学习的你，都能收获美好的前程！**\n\n- 承遇朝霞，年少正恰。\n- 整装戎马，刻印风华。\n\n# :bookmark: 目录\n\n- [`一、推荐`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#feet--%E4%B8%80%E6%8E%A8%E8%8D%90) - `日常推荐优秀书籍`\n- [`二、Java/Spring`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#coffee-%E4%BA%8Cjava) - `16本提升基本功的书籍`\n- [`三、DB`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#floppy_disk-%E4%B8%89db) - `2本数据库优秀书籍`\n- [`四、Redis`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#balloon-%E5%9B%9Bredis) - `深入学习Redis`\n- [`五、架构&设计`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#art-%E4%BA%94%E6%9E%B6%E6%9E%84%E8%AE%BE%E8%AE%A1) - `提升架构能力和编写优秀代码`\n- [`六、号主原创书籍[免费下载]`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#lollipop-%E5%85%AD%E5%8F%B7%E4%B8%BB%E5%8E%9F%E5%88%9B%E4%B9%A6%E7%B1%8D%E5%85%8D%E8%B4%B9%E4%B8%8B%E8%BD%BD) - `收集优秀原创技术号主PDF书籍`\n- [`七、其他系列`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#golf-%E4%B8%83%E5%85%B6%E4%BB%96%E7%B3%BB%E5%88%97) - `拓展学习技能增强个人能力`\n- [`八、人性`](https://github.com/fuzhengwei/CodeGuide/wiki/%E5%80%BC%E5%BE%97%E4%B8%80%E7%9C%8B%E7%9A%84%E5%A5%BD%E4%B9%A6#smile-%E5%85%AB%E4%BA%BA%E6%80%A7) - `提示心灵建设的书籍`\n\n## :feet:  一、推荐\n\n#### - [小傅哥的《重学 Java 设计模式》](https://download.csdn.net/download/Yao__Shun__Yu/19265731) ⭐⭐⭐⭐\n\n>本书是作者`小傅哥`，投入50天时间，从互联网实际业务开发中抽离出，交易、营销、秒杀、中间件、源码等22个真实业务场景，编写了18万字271页的实战型Java编程资料。如果书中含有不易理解的内容，一定是作者在编写的过程中缺少必要的描述和严格的校准，感谢把你的意见或者疑问提交给我，也欢迎与我多一些交互，互相进步共同成长。\n\n#### - [小傅哥的《Java 面经手册》](https://download.csdn.net/download/Yao__Shun__Yu/14932325) ⭐⭐⭐⭐\n\n>全书共计 5 章 29 节，417页11.5万字，耗时 4 个月完成。涵盖数据结构、算法逻辑、并发编程、JVM以及简历和互联网大厂面试等内容。但此书并不是单纯的面试题，也不是内卷八股文。而是从一个单纯的和程序员有关的数学知识点开始，深入讲解 Java 的核心技术。并且每一章节都配有实践验证的源码，可以对照着一起撸才更有感觉！\n\n#### - [小傅哥的《字节码编程》](https://download.csdn.net/download/Yao__Shun__Yu/12505051) ⭐⭐⭐\n\n>让人怪不好意思的，说是出书有点膨胀，毕竟这不是走出版社的流程，选题、组稿、编著、审读、加工到出版发行。但全书共计107页，11万7千字，20个章节涵盖三个字节码框架(ASM、Javassist、Byte-budy)和JavaAgent使用并附带整套案例源码！\n\n#### -  [《JAVA核心知识点整理》](#) ⭐⭐⭐⭐\n\n>一份整理的蛮不错的Java核心知识点。覆盖了JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等大量知识点。\n\n#### -  [计算机是怎样跑起来的(日)矢泽久雄](#) ⭐⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tyM62dh)\n\n>矢泽久雄，曾在Software House做过程序员，电脑作家之友会会长。工作之余笔耕不辍，从电路到编程语言均有涉及。代表作有《程序是怎样跑起来的》等。本书以图配文，以计算机的三大原则为开端、相继介绍了计算机的结构、手工汇编、程序流程、算法、数据结构、面向对象编程、数据库、TCP/IP 网络、数据加密、XML、计算机系统开发以及SE 的相关知识。\n\n#### -  [cxuan的《程序员必知的硬核知识大全》](#) ⭐⭐⭐⭐\n\n>浓缩了 CPU、内存、二进制、计算机硬件、应用、算法 的精华知识，以通俗易懂的形式给你讲出来，读者看完后一致好评，cxuan 呕心沥血的作品，文字是一行一行写的，图是一笔一笔画的，强烈推荐给大家。\n\n## :coffee: 二、Java\n\n#### 1. [《Java虚拟机规范(Java SE 7)》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/t1MGrVm)\n\n>如果不太熟悉jvm，这个读起来非常乏味（只有规范，没有多余解释），但如果阅读过相关深入java虚拟机，再读这个，会非常有亲切感。\n\n#### 2. [《深入理解Java虚拟机：JVM高级特性与最佳实践（第3版）》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tDMC2qu)\n\n>这是一部从工作原理和工程实践两个维度深入剖析JVM的著作，是计算机领域公认的经典，繁体版在台湾也颇受欢迎。作者周志明，是资深Java技术、机器学习和企业级开发技术专家，现任远光软件研究院院长，人工智能博士在读。\n\n#### 3. [《JAVA核心知识点整理》](#)⭐⭐⭐⭐\n\n>一份整理的蛮不错的Java核心知识点。覆盖了JVM、锁、并发、Java反射、Spring原理、微服务、Zookeeper、数据库、数据结构等大量知识点。\n\n#### 4. [《On Java 8 编程思想》](https://lingcoder.github.io/OnJava8/#/sidebar)⭐⭐⭐⭐ \n\n>本书原作者为 [美] Bruce Eckel，即《Java 编程思想》的作者。译者在翻译中同时参考了谷歌、百度、有道翻译的译文以及《Java编程思想》第四版中文版的部分内容（对其翻译死板，生造名词，语言精炼度差问题进行规避和改正）。最后结合译者自己的理解进行本地化，尽量做到专业和言简意赅，方便大家更好的理解学习。\n\n#### 5. [深入浅出+Java+多线程](#) ⭐⭐⭐⭐\n\n>笔者在读完市⾯上关于Java并发编程的资料后，感觉有些知识点不是很清晰，于是\n>在RedSpider社区内展开了对Java并发编程原理的讨论。鉴于开源精神，我们决定\n>将我们讨论之后的Java并发编程原理整理成书籍，分享给⼤家。 \n>`如果您或者您的单位愿意赞助本书或本社区，请发送邮件到RedSpider社区邮件组redspider@qun.mail.163.com或加微信redspider-worker进⾏洽谈。`\n\n#### 6. [《Java核心技术 I》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/t8C7Kf7)\n\n>不同于一般的 `Java`入门书，此书对api的讲解非常详细，细节部门颇多。举个例子，java对象序列化时会写入什么内容，本书都有详细的介绍\n\n#### 7. [《effective java 3》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tmMKWJm)\n\n>全书以一种比较松散的方式将这些条目组织成11章，每一章都涉及软件设计的一个主要方面。因此，本书并不一定需要按部就班地从头读到尾，因为每个条目都有一定程度的独立性。这些条目相互之间经常交叉引用，因此可以很容易地在书中找到自己需要的内容。\n\n#### 8. [《Java解惑》](#) ⭐⭐⭐\n\n>挺有意思的一本书，它列举了许多平常不太注意的细节问题，可能大部分时候我们都不会碰到此类问题，但如果读过，一旦碰到，就会留意此类问题。\n\n#### 9. [《Thinking In Java 4》](#) ⭐⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tHChOOP)\n\n>值得用2年深入抚摸的书籍，对于学习java技术除了最开始的入门书籍后，这是一本非常值得阅读的书籍。\n\n#### 10. [《Java内存模型》](#) ⭐⭐⭐⭐\n\n>Java线程之间的通信由Java内存模型（本文简称为JMM）控制，JMM决定一个线程对共享变量的写入何时对另一个线程可见。从抽象的角度来看，JMM定义了线程和主内存之间的抽象关系：线程之间的共享变量存储在主内存（main memory）中，每个线程都有一个私有的本地内存（local memory），本地内存中存储了该线程以读/写共享变量的副本。本地内存是JMM的一个抽象概念，并不真实存在。它涵盖了缓存，写缓冲区，寄存器以及其他的硬件和编译器优化。\n\n#### 11. [《Java并发编程实践(全)》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tAMi4DW)\n\n>随着多核处理器的普及，使用并发成为构建高性能应用程序的关键。Java 5以及6在开发并发程序中取得了显著的进步，提高了Java虚拟机的性能以及并发类的可伸缩性，并加入了丰富的新并发构建块。在《JAVA并发编程实践》中，这些便利工具的创造者不仅解释了它们究竟如何工作、如何使用，还阐释了创造它们的原因，及其背后的设计模式。\n\n#### 12. [《Spring揭秘》](#) ⭐⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tLMQEI6)\n\n**本书内容全面，论述深刻入理，必将成为每个Java专业开发人员必备的Spring图书。**\n\n>难得的国产良心技术书籍，既没有大量堆砌Spring源码，也没有原封不动地翻译官方文档。作者以自己的深厚功力和独特视角一步一步地把Spring框架抽丝剥茧地展现在读者面前，从谋篇布局和字里行间都能看出作者的用心之处。如果你想深入了解Spring的方方面面，这本书非读不可，而且读一遍都不够，要每隔一段时间反复阅读，尤其第二部分IOC和第三部分AOP，它们是Spring的基础，也是这本书的精华所在。这里不妨给个建议，以这本书为蓝本把Spring框架用到的设计模式和原则认真梳理一遍，结合源码认真理解为何要这样设计。如若这样，假以时日，功力必有小成啊。最后感谢作者，感谢我能遇到这本书\n\n#### 13. [《Spring源码深度解析》](#) ⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tkMu8o1)\n\n>由浅入深、由易到难地对Spring源码展开了系统的讲解，包括Spring的设计理念和整体架构、容器的基本实现、默认标签的解析、自定义标签的解析、bean的加载、容器的功能扩展、AOP、数据库连接JDBC、整合MyBatis、事务、SpringMVC、远程服务、Spring消息服务等内容。\n\n#### 14. [《深入理解SpringCloud与微服务构建》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tqCFEn2)\n\n>本书以微服务的基本概念介绍性开篇，逐步引出Java平台下打造微服务的利器SpringBoot微框架。书中从SpringBoot微框架的“出身”开始，循序渐进，为大家剖析SpringBoot微框架的设计理念和原理，并对框架的重点功能和模块进行了逐一讲解。\n\n#### 15. [《美团技术后台篇》](#) ⭐⭐⭐⭐\n\n>2019年美团点评高级技术汇总，深入且清晰设计到Java核心技术。包括；字节码编程、全链路监控、美团分布式 ID 生成服务开源等。\n\n#### 16. [Java Concurrency in Practice](#) ⭐⭐⭐⭐⭐\n\n>This book covers:\n>Basic concepts of concurrency and thread safety\n>Techniques for building and composing thread-safe classes\n>Using the concurrency building blocks in java.util.concurrent\n>Performance optimization dos and don\'ts\n>Testing concurrent programs\n>Advanced topics such as atomic variables, nonblocking algorithms, and the Java Memory Model\n\n#### 17. [小傅哥的《手写MyBatis》](https://download.csdn.net/download/Yao__Shun__Yu/21009038) ⭐⭐⭐⭐⭐\n\n>在手写的过程中学习 Mybatis 从解析、绑定、反射、缓存，到会话和事务操作，以及如何与 Spring 进行关联注册 Bean 对象，完成整合部分功能逻辑。通过这些内容的拆解实现，读者伙伴就可以非常清楚的知道这些核心功能都是如何实现的了，以后再阅读 Mybatis 源码也就知道从哪开始到哪结束了。\n\n\n## :floppy_disk: 三、DB\n\n#### 1. [《MySQL王者晋级之路》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tEMuHEB)\n\n>十年磨一剑，汇集作者多年MySQL数据库领域的一线实战与教学经验，由浅入深剖析MySQL的体系结构、备份恢复、复制、高可用集群架构、优化、故障排查、新版本特性、监控、升级及技术面试宝典等知识点。\n\n#### 2. [《数据库索引设计与优化》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/toC5pSC)\n\n>作者通过系统的讲解及大量的案例清晰地阐释了关系型数据库的访问路径选择原理，以及表和索引的扫描方式，详尽地讲解了如何快速地估算SQL 运行的CPU 时间及执行时间，帮助读者从原理上理解SQL、表及索引结构、访问方式等对关系型数据库造成的影响，并能够运用量化的方法进行判断和优化，指导关系型数据库的索引设计。此书适用于已经具备了SQL 这一关系型语言相关知识，希望通过理解SQL 性能相关的内容，或者希望通过了解如何有效地设计表和索引而从中获益的人员。\n\n#### 3. MYSQL技术内幕：INNODB存储引擎 - ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tdMMMh6)\n\n>这本书更深入地介绍InnoDB存储引擎的内核，例如latch、B+树索引、事务、锁等，从源代码的角度深度解析了InnoDB的体系结构、实现原理、工作机制，并给出了大量最佳实践，帮助用户真正了解一个数据库存储引擎的开发。\n\n## :balloon: 四、Redis\n\n#### 1. [《Redis设计与实现》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tCMuaUt)\n\n>黄健宏 软件开发者，他喜欢函数式编程，热爱开源软件。出于对数据库的强烈兴趣，他开始阅读和分析 Redis 源代码，并对 Redis 2.6 和 Redis 3.0 的源代码进行了详细注释。\n\n#### 2. [《Redis 深度历险：核心原理与应用实践》](http://book.bugstack.cn/#s/5z4EfQIQ) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tDM6pVa)\n\n>作者：钱文品，老钱。可以说这是一本深挖到redis骨头的技术书籍，整个内容涵盖；基础和应用篇、原理篇、集群篇、拓展篇、源码篇共 5 大块内容，值得学习。\n\n#### 3. [《Redis开发与运维》](http://book.bugstack.cn/#s/54LyVtFw) ⭐⭐⭐⭐- [*点击购买(支持作者)*](http://u.jd.com/t2CmVck)\n\n>付磊，张益军 | 搜狐视频高级研发工程师，都拥有多年Redis开发运维经验，为公司多个核心业务提供Redis服务。两人共同编写了本书，在本书中全面讲解Redis基本功能及其应用，并结合线上开发与运维监控中的实际使用案例，深入分析并总结了实际开发运维中遇到的“陷阱”，以及背后的原因， 包含大规模集群开发与管理的场景、应用案例与开发技巧，为高效开发运维提供了大量实际经验和建议。\n\n## :art: 五、架构&设计\n\n#### 1. [《代码整洁之道》](http://book.bugstack.cn/#s/5z4I_vwg) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/txM8NQ0)\n\n>本书提出一种观念：代码质量与其整洁度成正比。干净的代码，既在质量上较为可靠，也为后期维护、升级奠定了良好基础。作为编程领域的佼佼者，本书作者给出了一系列行之有效的整洁代码操作实践。\n\n#### 2. [《Head_First设计模式(中文版)》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tQCVCRW)\n\n>Head First陆续的介绍了策略模式、观察者模式、装饰者模式、工厂方法模式、抽象工厂模式、单件模式、命令模式、适配器模式、外观模式、模板方法模式、迭代器模式、组合模式、状态模式、代理模式，在介绍各种模式的期间，用简单的应用场景、通俗的语言引导读者去思考这些模式是如何利用和遵循相应OO原则的，然后再清晰的总结出每种模式的定义。\n\n#### 3. [《编写可读代码的艺术》](#) ⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tCC7Gg5)\n\n>细节决定成败，思路清晰、言简意赅的代码让程序员一目了然；而格式凌乱、拖沓冗长的代码让程序员一头雾水。除了可以正确运行以外，优秀的代码必须具备良好的可读性，编写的代码要使其他人能在最短的时间内理解才行。本书旨在强调代码对人的友好性和可读性。\n\n#### 4. 《重构 改善既有代码的设计》 ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tqM3q81)\n\n> “不要容忍破窗户” 如果两个或更多的地方实现同一职责，则改变时会带来麻烦。所以要遵循DRY原则，单一职责。这本书的每一项都介绍一种经过实证的代码变换手法（code transformation）的动机和技术。向你讲述如何有效的重构以及是否进行重构。\n\n#### 5. 《设计数据密集型应用 Designing Data Intensive Applications》 ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tHMz71Y) \n\n>作者是英国剑桥大学的一名分布式系统研究员，在此之前他曾是软件工程师和企业家，在 Linkedin 和 Rapportive 工作过，从事大规模数据基础设施相关的工作。书中包含：深入分析你已经在使用的系统，并学习如何更高效地使用和运维这些系统、理解分布式系统研究，这些研究是现代数据库构建的基石、了解一致性、可伸缩性、容错性和复杂度之间的权衡。*推荐人：BK*\n\n#### 6. 《企业应用架构模式》 ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tBM31CH) \n\n>作者是当今面向对象软件开发的权威，他在一组专家级合作者的帮助下，将40多种经常出现的解决方案转化成模式，最终写成这本能够应用于任何一种企业应用平台的、关于解决方案的、不可或缺的手册。\n\n## :lollipop: 六、号主原创书籍[下载]\n\n#### 1. [小傅哥的《字节码编程》](https://download.csdn.net/download/Yao__Shun__Yu/12505051) ⭐⭐⭐\n\n>让人怪不好意思的，说是出书有点膨胀，毕竟这不是走出版社的流程，选题、组稿、编著、审读、加工到出版发行。但全书共计107页，11万7千字，20个章节涵盖三个字节码框架(ASM、Javassist、Byte-budy)和JavaAgent使用并附带整套案例源码！\n\n#### 2. [小傅哥的《重学 Java 设计模式》](https://download.csdn.net/download/Yao__Shun__Yu/19265731) ⭐⭐⭐⭐\n\n>本书是作者`小傅哥`，投入50天时间，从互联网实际业务开发中抽离出，交易、营销、秒杀、中间件、源码等22个真实业务场景，编写了18万字271页的实战型Java编程资料。如果书中含有不易理解的内容，一定是作者在编写的过程中缺少必要的描述和严格的校准，感谢把你的意见或者疑问提交给我，也欢迎与我多一些交互，互相进步共同成长。\n\n#### 3. [《Java 基础核心总结》](#) ⭐⭐⭐\n\n>这本 PDF 非常适合 Java 小白和其他语言转型的程序员，涉及的面非常广、语言比较简练，通俗易懂的把 Java 所有特性、语法概念都给你讲出来，这是第一版，以后还会持续更新，推荐给小伙伴们。\n\n#### 4. [《HTTP 超全汇总》](#) ⭐⭐⭐\n\n>把关于 HTTP 协议 90% 的内容都讲出来了，非常全的一本 PDF，可以作为速查手册，也可以当作培训教材，作者写了将近两个月的作品，推荐给大家。\n\n#### 5. [《程序员必知的硬核知识大全》](#) ⭐⭐⭐⭐\n\n>浓缩了 CPU、内存、二进制、计算机硬件、应用、算法 的精华知识，以通俗易懂的形式给你讲出来，读者看完后一致好评，cxuan 呕心沥血的作品，文字是一行一行写的，图是一笔一笔画的，强烈推荐给大家。\n\n#### 6. [阿宝哥的《前端进阶篇》](#) ⭐⭐⭐\n\n>“玩转前端专题” 包含玩转 Video 播放器、玩转图片处理、玩转 Word 文档、玩转混合加密和玩转网络五大章节的内容。而 “你不知道的 XXX 专题” 包含你不知道的 Web Workers、你不知道的 WebSocket、你不知道的 Blob 及你不知道的 WeakMap 四大章节的内容。\n\n#### 7. [阿宝哥的《重学TS》](#) ⭐⭐⭐⭐\n\n> “重学TS” 共 228 页包含了 TypeScript 快速入门篇、九种常见的 TypeScript 设计模式、TypeScript 进阶之插件化架构、控制反转与依赖注入及编写高效 TypeScript 代码的一些建议。\n\n## :golf: 七、其他系列\n\n#### 1. [《阿里工程师的自我修养》](#) ⭐⭐⭐⭐\n\n>从入门到进阶，从普通员工到主管，从知识到落地，从量的积累到质的飞跃，在不确定性的世界中，你遇到的种种难题，阿里工程师正在探索着最优解。3大思维、10个技巧、10年感悟……每经过一次大的战役，阿里工程师都会复盘、沉淀，这些经验值得细品。\n\n#### 2. [Java开发手册（嵩山版）](#) ⭐⭐⭐⭐\n\n>《阿里巴巴 Java 开发手册》主要提炼了阿里巴巴集团技术团队的集体编程经验和软件设计智慧，可全面、立体地帮助开发者的成长和团队代码文化形成。嵩山版首次新增前后端规约等内容，可帮助开发者码出规范，码出质量。\n\n#### 3. [《Http权威指南》](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tCCkwTD)\n\n>如果以前没有深入了解http，读了此书，会觉得以前了解的关于http的内容都弱爆了。经典书籍，中文版2012年发版，翻译的还不错，值得阅读。\n\n#### 4. [Elasticsearch 权威指南 中文版](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tjMzqw3)\n\n>这本指南都会帮助你了解其中最基本的概念，从最基本的操作开始学习 Elasticsearch。同时将向你介绍讲解结构化搜索、统计、查询过滤、地理定位、自动完成以及你是不是要查找的提示。并且探讨如何给数据建模能提升 Elasticsearch 的性能，以及在生产环境中如何配置、监视你的集群。\n\n#### 5. [计算机是怎样跑起来的(日)矢泽久雄](#) ⭐⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tiM6EOb)\n\n>矢泽久雄，曾在Software House做过程序员，电脑作家之友会会长。工作之余笔耕不辍，从电路到编程语言均有涉及。代表作有《程序是怎样跑起来的》等。本书以图配文，以计算机的三大原则为开端、相继介绍了计算机的结构、手工汇编、程序流程、算法、数据结构、面向对象编程、数据库、TCP/IP 网络、数据加密、XML、计算机系统开发以及SE 的相关知识。\n\n#### 6. [编码：隐匿在计算机软硬件背后的语言](#) ⭐⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tpCkJAn)\n\n>是一本讲述计算机工作原理的书。不过，你千万不要因为“工作原理”之类的字眼就武断地认为它是晦涩而难懂的。作者用丰富的想象和清晰的笔墨将看似烦杂的理论阐述得通俗易懂，你丝毫不会感到枯燥和生硬。更重要的是，你会因此更加深刻地理解计算机的工作原理。这种理解不是抽象层面上的，而是具有一定深度的，这种深度甚至不逊于“电气工程师”和“程序员”的理解。\n\n#### 7. [计算机程序的构造和解释(原书第2版)](#) ⭐⭐⭐⭐⭐\n\n>《计算机程序的构造和解释(原书第2版)》1984年出版，成型于美国麻省理工学院(MIT)多年使用的一本教材，1996年修订为第2版。在过去的二十多年里，《计算机程序的构造和解释(原书第2版)》对于计算机科学的教育计划产生了深刻的影响。第2版中大部分重要程序设计系统都重新修改并做过测试，包括各种解释器和编译器。作者根据其后十余年的教学实践，还对其他许多细节做了相应的修改。\n\n#### 8. [代码大全（第2版）](https://book.douban.com/subject/1477390/) ⭐⭐⭐⭐⭐\n\n>第2版的《代码大全》是著名IT畅销书作者史蒂夫·迈克康奈尔11年前的经典著作的全新演绎：第2版不是第一版的简单修订增补，而是完全进行了重写；增加了很多与时俱进的内容。这也是一本完整的软件构建手册，涵盖了软件构建过程中的所有细节。它从软件质量和编程思想等方面论述了软件构建的各个问题，并详细论述了紧跟潮流的新技术、高屋建瓴的观点、通用的概念，还含有丰富而典型的程序示例。\n\n#### 9. [编程匠艺](https://book.douban.com/subject/6904647/) ⭐⭐⭐⭐\n\n>如果你可以编写出合格的代码，但是想更进一步、创作出组织良好而且易于理解的代码，并希望成为一名真正的编程专家或提高现有的职业技能，那么Pete Goodliffe编写的这本本书都会为你给出答案。本书的内容涵盖编程的各个要素，如代码风格、变量命名、错误处理和安全性等。此外，本书还对一些更广泛的编程问题进行了探讨，如有效的团队合作、开发过程和文档编写，等等。\n\n#### 10. [Zookeeper 分布式过程](#) ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/tFCkcei)\n\n>作者介绍Flavio Junqueira 是微软研究院在英国剑桥大学的研究人员之一。他拥有美国加州大学圣地亚哥分校计算机科学博士学位。他的研究范围涉及分布式系统的各个方面，包括分布式算法、并发性和可扩展性。他是Apache项目如Apache ZooKeeper（PMC主席和提交者）和Apache BookKeeper（提交者）的积极贡献者。他一有空就喜欢睡觉。\n\n#### 11. 黑客与画家 ⭐⭐⭐⭐ - [*点击购买(支持作者)*](http://u.jd.com/t1MbplW)\n\n>本书是硅谷创业之父Paul Graham 的文集，主要介绍黑客即优秀程序员的爱好和动机，讨论黑客成长、黑客对世界的贡献以及编程语言和黑客工作方法等所有对计算机时代感兴趣的人的一些话题。书中的内容不但有助于了解计算机编程的本质、互联网行业的规则，还会帮助读者了解我们这个时代，迫使读者独立思考。\n\n## :smile: 八、人性\n\n- 《非暴力沟通》(美)卢森堡\n- 《逆商：我们该如何应对坏事件》\n- 《超越自卑》阿德勒 \n- 《关键对话-如何高效能沟通》\n- 《人月神话》 - 这是一本经典著作，与软件开发有关的每一个人都应该不止一遍地读这本书\n----\n\n*以上PDF书籍链接皆来自网络分享，如果涉及版权和付费等任何问题，立即删除。同时本页只作为宣传帮助作者推广，下载试读PDF后请及时删除并购买正版书籍。*');

-- ----------------------------
-- Table structure for wiki_tasks
-- ----------------------------
DROP TABLE IF EXISTS `wiki_tasks`;
CREATE TABLE `wiki_tasks`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务ID',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `source_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源ID',
  `task_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'ingest' COMMENT '任务类型: ingest/rescan/lint',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'pending' COMMENT '状态: pending/running/completed/failed',
  `progress` int NULL DEFAULT 0 COMMENT '进度(0-100)',
  `total_steps` int NULL DEFAULT 0 COMMENT '总步骤数',
  `done_steps` int NULL DEFAULT 0 COMMENT '已完成步骤数',
  `result_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '结果JSON',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '错误信息',
  `created_at` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时间',
